package org.jfree.chart.block;

import java.awt.Graphics2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.block.Block.Position;
import org.jfree.chart.block.RectangleConstraint;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.Size2D;
import org.jfree.data.Range;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BorderArrangement.arrangeFF
 */
public class BorderArrangement_arrangeFF_TriageGen1Test {

    private BorderArrangement arrangement;
    private BlockContainer mockContainer;
    private Graphics2D mockGraphics2D;
    private RectangleConstraint constraint;

    // Since arrangeFF is protected, we use a subclass to expose it for testing
    private static class TestableBorderArrangement extends BorderArrangement {
        public Size2D callArrangeFF(BlockContainer container, Graphics2D g2, RectangleConstraint constraint) {
            return super.arrangeFF(container, g2, constraint);
        }

        // Helper to inject blocks via reflection or manual setting if fields are private
        // Based on the logic, the class has fields: topBlock, bottomBlock, leftBlock, rightBlock, centerBlock
        // We will use a trick: BorderArrangement.add(Block, Object) is public.
        // The keys for BorderArrangement are typically Position constants.
    }

    @Before
    public void setUp() {
        arrangement = new TestableBorderArrangement();
        mockContainer = mock(BlockContainer.class);
        mockGraphics2D = mock(Graphics2D.class);
        constraint = new RectangleConstraint(100.0, 100.0);
    }

    @Test
    public void testArrangeFF_AllBlocksNull() {
        Size2D result = ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(100.0, result.getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyTopBlock() {
        Block topBlock = mock(Block.class);
        when(topBlock.arrange(any(), any())).thenReturn(new Size2D(100.0, 20.0));
        arrangement.add(topBlock, Position.TOP);

        Size2D result = ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(100.0, result.getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(topBlock).setBounds(captor.capture());
        assertEquals(0.0, captor.getValue().getX(), 0.001);
        assertEquals(0.0, captor.getValue().getY(), 0.001);
        assertEquals(20.0, captor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyBottomBlock() {
        Block bottomBlock = mock(Block.class);
        when(bottomBlock.arrange(any(), any())).thenReturn(new Size2D(100.0, 30.0));
        arrangement.add(bottomBlock, Position.BOTTOM);

        Size2D result = ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        assertEquals(100.0, result.getWidth(), 0.001);
        assertEquals(100.0, result.getHeight(), 0.001);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(bottomBlock).setBounds(captor.capture());
        // h[0] is 0, h[2] is 100-30-0 = 70. Bounds Y = h[0] + h[2] = 70
        assertEquals(70.0, captor.getValue().getY(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyLeftBlock() {
        Block leftBlock = mock(Block.class);
        // h[0]=0, h[1]=0, h[2]=100.
        when(leftBlock.arrange(any(), any())).thenReturn(new Size2D(40.0, 100.0));
        arrangement.add(leftBlock, Position.LEFT);

        Size2D result = ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(leftBlock).setBounds(captor.capture());
        assertEquals(40.0, captor.getValue().getWidth(), 0.001);
        assertEquals(100.0, captor.getValue().getHeight(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyRightBlock() {
        Block rightBlock = mock(Block.class);
        // w[2] will be 0 because left block is null.
        when(rightBlock.arrange(any(), any())).thenReturn(new Size2D(30.0, 100.0));
        arrangement.add(rightBlock, Position.RIGHT);

        ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        ArgumentCaptor<Rectangle2D.Double> captor = ArgumentCaptor.forClass(Rectangle2D.Double.class);
        verify(rightBlock).setBounds(captor.capture());
        // w[2]=0, w[4]=100-30-0=70. X = w[2]+w[4] = 70.
        assertEquals(70.0, captor.getValue().getX(), 0.001);
    }

    @Test
    public void testArrangeFF_OnlyCenterBlock() {
        Block centerBlock = mock(Block.class);
        arrangement.add(centerBlock, Position.CENTER);

        ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        verify(centerBlock).arrange(any(), any());
        verify(centerBlock).setBounds(any(Rectangle2D.Double.class));
    }

    @Test
    public void testArrangeFF_FullScenario() {
        // Top: 20 height
        Block top = mock(Block.class);
        when(top.arrange(any(), any())).thenReturn(new Size2D(100.0, 20.0));
        arrangement.add(top, Position.TOP);

        // Bottom: 30 height
        Block bottom = mock(Block.class);
        when(bottom.arrange(any(), any())).thenReturn(new Size2D(100.0, 30.0));
        arrangement.add(bottom, Position.BOTTOM);

        // Left: 40 width. h[2] = 100 - 30 - 20 = 50.
        Block left = mock(Block.class);
        when(left.arrange(any(), any())).thenReturn(new Size2D(40.0, 50.0));
        arrangement.add(left, Position.LEFT);

        // Right: 20 width. w[2]=40. w[4] = 100 - 20 - 40 = 40. X = 40 + 40 = 80.
        Block right = mock(Block.class);
        when(right.arrange(any(), any())).thenReturn(new Size2D(20.0, 50.0));
        arrangement.add(right, Position.RIGHT);

        // Center: w[4]=40, h[4]=50. X=40, Y=20.
        Block center = mock(Block.class);
        arrangement.add(center, Position.CENTER);

        ((TestableBorderArrangement) arrangement).callArrangeFF(mockContainer, mockGraphics2D, constraint);

        // Verify Top
        verify(top).setBounds(new Rectangle2D.Double(0.0, 0.0, 100.0, 20.0));
        // Verify Bottom: Y = h[0] + h[2] = 20 + 50 = 70
        verify(bottom).setBounds(new Rectangle2D.Double(0.0, 70.0, 100.0, 30.0));
        // Verify Left: Y = h[0] = 20
        verify(left).setBounds(new Rectangle2D.Double(0.0, 20.0, 40.0, 50.0));
        // Verify Right: X = w[2] + w[4] = 40 + 40 = 80
        verify(right).setBounds(new Rectangle2D.Double(80.0, 20.0, 20.0, 50.0));
        // Verify Center: X = 40, Y = 20, W = 40, H = 50
        verify(center).setBounds(new Rectangle2D.Double(40.0, 20.0, 40.0, 50.0));
    }
}
